{
  "米塔专属场景": [
    {
      "疯狂米塔的伪装场景": {
        "场景名称": "米塔之家",
        "核心设计理念": "通过极致的生活化细节掩盖异常",
        "场景布局": [
          {
            "区域": "客厅",
            "正常元素": [
              "布艺沙发搭配针织毯",
              "播放田园风光的液晶电视",
              "堆满零食的木质茶几"
            ],
            "隐藏机制": [
              "沙发坐垫夹层藏有神经抑制装置（触发后降低玩家移动速度）",
              "电视柜抽屉的螺丝孔实为通风毒气的微型出口"
            ]
          },
          {
            "区域": "厨房",
            "正常元素": [
              "装满新鲜食材的冰箱",
              "正在炖煮浓汤的砂锅",
              "悬挂整齐的烘焙工具"
            ],
            "隐藏机制": [
              "冰箱第二层设置重力陷阱（取物超过3次自动锁死厨房门）",
              "调味罐内置情绪调节药剂（随机替换盐和糖的位置）"
            ]
          },
          {
            "区域": "卧室",
            "正常元素": [
              "铺着碎花床单的双人床",
              "用来传送的巨大装置",
              "摆满护肤品的梳妆台",
              "挂着连衣裙的开放式衣柜"
            ],
            "隐藏机制": [
              "衣柜里有着通往地下室入口",
              "梳妆台采用单向透视玻璃（背后隐藏监控室）"
