      "互动要素": [
        "帮居民修理发条装置",
        "在茶杯泳池举办救援演习",
        "书架间的绳索滑梯"
      ]
    },
    {
      "角色": "短发米塔「昂首阔步的信念」",
      "场景名称": "版本导航站",
      "场景特征": [
        "布满全息投影的环形控制室",
        "地面镶嵌发光版本号地砖",
        "墙壁展示各版本概念设计图",
        "工作台摆放破损的米塔核心"
      ],
      "互动要素": [
        "操作投影仪讲解版本差异",
        "修复新手米塔的引导程序",
        "解锁穿梭通道的密码谜题"
      ]
    },
    {
      "角色": "善良米塔「愈发善良的希望」",
      "场景名称": "跨版本庇护所",
      "场景特征": [
        "纯白色调的多层避难所",
        "医疗室配备万能修复舱",
        "战略室的沙盘实时显示危机点",
        "天台种植发光药草园"
      ],
      "互动要素": [
        "调配跨版本治疗药剂",
        "部署救援无人机",
        "破译加密的警报信号"
      ]
    },
    {
      "角色": "帽子米塔「值得托付的信任」",
      "场景名称": "节奏工坊",
      "场景特征": [
        "霓虹灯管装饰的舞蹈教室",
        "DJ台连接着全息编曲界面",
        "墙壁挂满冠军奖章",
        "隐藏的录音室储存未公开demo"
      ],
      "互动要素": [
        "双人节奏游戏机",
        "定制专属应援曲",
        "解谜获得限定皮肤"
