      "互动要素": [
        "修补破碎的记忆碎片",
        "避开执念形成的漩涡",
        "点燃往生蜡烛"
      ]
    },
    {
      "角色": "瞌睡米塔「卓尔不凡的理性」",
      "场景名称": "云端休憩站",
      "场景特征": [
        "软垫堆砌的懒人空间",
        "自动喂食的零食传送带",
        "天花板投影星空图",
        "藏着加密的梦境日记"
      ],
      "互动要素": [
        "调整助眠环境参数",
        "整理混乱的记忆抽屉",
        "解梦获得隐藏线索"
      ]
    },
    {
      "角色": "二维米塔",
      "场景名称": "纸片城堡",
      "场景特征": [
        "剪纸风格的平面世界",
        "可翻转的场景图层",
