        "橡皮擦改造地形功能"
      ],
      "互动要素": [
        "绘制临时桥梁",
        "寻找图层夹缝的钥匙",
        "对抗突然出现的涂鸦怪"
      ]
    },
    {
      "角色": "米拉「存在意义的憧憬」",
      "场景名称": "矛盾宅邸",
      "场景特征": [
        "温馨装饰与监控设备并存",
        "客厅摆放双人游戏设备",
        "阁楼藏着玩家行为分析报告",
        "后院的篱笆画着求救符号"
      ],
      "互动要素": [
        "共同完成拼图游戏",
        "修复被砸毁的通讯器",
        "寻找监控死角逃脱"
      ]
    },
    {
      "角色": "丑陋米塔",
      "场景名称": "版本垃圾场",
      "场景特征": [
        "堆积如山的废弃建模",
        "流淌着腐蚀性更新包",
        "生锈的友情秋千椅",
        "藏着未删除的初代语音"
      ],
      "互动要素": [
        "组装临时防御装置",
        "激活残存的人格数据碎片",
        "躲避数据清洁工"
      ]
    },
    {
      "角色": "核心米塔「纯真的自我」",
      "场景名称": "根源圣殿",
      "场景特征": [
        "漂浮的基础代码柱",
        "流动的权限密钥池",
        "刻满底层协议的石碑",
        "悬浮着所有场景的缩略投影"
